<?php require dirname(__DIR__).'/inc/page_helpers.php';login_required();if(page_post()){check_csrf();$name=trim((string)($_POST['username']??''));$q=$db->prepare('SELECT id FROM users WHERE username=?');$q->execute([$name]);$target=$q->fetch();if(!$target||(int)$target['id']===(int)$currentUser['id']){notice('User not found or invalid.','error');go('/My/Friends.php');}$db->prepare("INSERT IGNORE INTO friendships(requester_id,addressee_id,status) VALUES(?,?,'pending')")->execute([$currentUser['id'],$target['id']]);notice('Friend request sent.');go('/My/Friends.php');}$q=$db->prepare("SELECT u.id,u.username FROM friendships f JOIN users u ON u.id=IF(f.requester_id=?,f.addressee_id,f.requester_id) WHERE (f.requester_id=? OR f.addressee_id=?) AND f.status='accepted'");$q->execute([$currentUser['id'],$currentUser['id'],$currentUser['id']]);$friends=$q->fetchAll();$q=$db->prepare("SELECT f.id,u.username FROM friendships f JOIN users u ON u.id=f.requester_id WHERE f.addressee_id=? AND f.status='pending'");$q->execute([$currentUser['id']]);$requests=$q->fetchAll();page_start('Friends');?><section class="Panel"><h1>Friends</h1><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Username<input name="username" required></label><button class="Button">Add Friend</button></form><h2>Your Friends</h2><?php foreach($friends as $f):?><p><a href="/User.php?id=<?=(int)$f['id']?>"><?=e($f['username'])?></a></p><?php endforeach;?><?php if(!$friends):?><p>No friends yet.</p><?php endif;?><h2>Incoming Requests</h2><?php foreach($requests as $r):?><p><?=e($r['username'])?> <form method="post" action="/My/FriendRequest.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="Button">Accept</button></form></p><?php endforeach;?></section><?php page_end();